  cmd: "printf 'raw source macros: '; rg -o '\\\\source\\{' blueprint/src/chapters | wc -l; printf 'env source anchors: '; perl -0777 -ne 'while (/\\\\begin\\{(definition|lemma|theorem|proposition|corollary|remark)\\}(?:\\[[^]]*\\])?(.*?)\\\\end\\{\\1\\}/sg) { $N++ if $2 =~ /\\\\source\\{/ } END {print \"$N\\n\"}' blueprint/src/chapters/*.tex; printf 'literal prose source refs: '; rg -n '\\\\verb.*\\\\source' blueprint/src/chapters | wc -l",
  workdir: ".",
  yield_time_ms: 10000,
  max_output_tokens: 3000
});
text(r.output);

const r = await tools.exec_command({cmd:"python -c 'import yaml, pathlib, re, json; root=pathlib.Path("hgraph/nodes"); rows=[]; marker=re.compile(r"\\b(REFERENCE|ADAPTED|CUSTOM|TO CHECK)\\b"); prov={"REFERENCE","ADAPTED","CUSTOM"}; out=[]
for p in root.glob("*.md"):
    txt=p.read_text(errors="replace"); parts=txt.split("---",2)
    if len(parts)<3: continue
    try: m=yaml.safe_load(parts[1]) or {}
    except Exception: continue
    tags=m.get("tags") or []; tags=[tags] if isinstance(tags,str) else list(tags); blob=txt
    seen=[x for x in ("REFERENCE","ADAPTED","CUSTOM","TO CHECK") if re.search(r"(?<![A-Za-z])"+re.escape(x)+r"(?![A-Za-z])",blob)]
    if seen: out.append({"id":p.stem,"type":m.get("type"),"title":m.get("title"),"tags":tags,"seen":seen,"doc":m.get("docstring","")[:100]})
print(json.dumps({"marker_nodes":len(out),"tag_counts":{t:sum(t in (r["tags"] or []) for r in out) for t in ("REFERENCE","ADAPTED","CUSTOM","TO CHECK")},"unmirrored":[r for r in out if any(t not in r["tags"] for t in r["seen"])],"tagged":out},indent=2))'","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild","yield_time_ms":30000,"max_output_tokens":30000});
text(r.output);

